window.NIDO_REVIEWS={"momo-toh":[{"name":"Jesús","loc":"","date":"2026-08","stars":5,"photo":"data:image/jpeg;base64,","en":"The views are amazing. I would definitely come back. The stay was very pleasant, and the co-hosts were very helpful at all times. There are coffee shops and stores nearby. The concept is very natural and spiritual, very good.","es":"Las vistas son increíbles. Sin duda volvería. La estancia fue muy agradable y los coanfitriones fueron muy serviciales en todo momento. Hay cafeterías y tiendas cerca. El concepto es muy natural y espiritual, muy bueno."},{"name":"Katia","loc":"Morelia, México","date":"2026-08","stars":5,"photo":"data:image/jpeg;base64,","en":"Our stay was super nice. The house is very beautiful and we really enjoyed the private terrace.","es":"Nuestra estancia fue súper agradable. La casa es muy bonita y disfrutamos mucho la terraza privada."},{"name":"Samara","loc":"Ciudad de México","date":"2026-08","stars":5,"photo":"data:image/jpeg;base64,","en":"Thank you very much. It's a beautiful place, and the magical garden is very close, as is the YMCA.","es":"Muchas gracias. Es un lugar hermoso, y el jardín mágico queda muy cerca, igual que la YMCA."},{"name":"Adolfo","loc":"Ciudad de México","date":"2026-08","stars":5,"photo":"data:image/jpeg;base64,","en":"I have been going to Tepoz for many years, and this has been one of my best experiences. The view is the best of all the places, the terrace is wonderful, and the energy of the place and the people is super nice. Thank you.","es":"Llevo muchos años yendo a Tepoz y esta ha sido una de mis mejores experiencias. La vista es la mejor de todos los lugares, la terraza es maravillosa y la energía del lugar y de la gente es súper linda. Gracias."},{"name":"Renata","loc":"","date":"2026-07","stars":5,"photo":"data:image/jpeg;base64,","en":"Cozy, clean, organized house. Communication with the staff is great; they are kind. We stayed in a room with 3 windows and 2 balconies. For those who need/appreciate ventilation, it's perfect. The view is beautiful. Across the street there is a trail to a pyramid, and it is worth getting information on how to get there.","es":"Casa acogedora, limpia y organizada. La comunicación con el equipo es excelente; son amables. Nos quedamos en un cuarto con 3 ventanas y 2 balcones. Para quien necesita o aprecia la ventilación, es perfecto. La vista es hermosa. Enfrente hay un sendero a una pirámide y vale la pena informarse sobre cómo llegar."},{"name":"Paloma","loc":"Champigny-sur-Marne, Francia","date":"2026-05","stars":5,"photo":"data:image/jpeg;base64,","en":"I loved my stay in this room, located in Ixcatepec, which is easily accessible from the center with public transportation running every 6–8 minutes, or on foot for those who enjoy a walk. The hosts were responsive, offered good advice, and are genuinely committed to this house. Everything was beautiful and as described; expectations were exceeded. I already know I'll be back.","es":"Me encantó mi estancia en este cuarto, en Ixcatepec, de fácil acceso desde el centro con transporte público cada 6–8 minutos, o a pie para quien disfruta caminar. Los anfitriones respondieron rápido, dieron buenos consejos y están de verdad comprometidos con esta casa. Todo era hermoso y tal como se describe; superó mis expectativas. Ya sé que volveré."},{"name":"Guillermo","loc":"Puebla, México","date":"2026-04","stars":5,"photo":"data:image/jpeg;base64,","en":"A simple, pleasant place with enough space for a comfortable night's sleep. Great value for money and good communication from the host.","es":"Un lugar sencillo y agradable, con espacio suficiente para dormir cómodo. Excelente relación calidad-precio y buena comunicación con el anfitrión."}],"blue-clover":[{"name":"Enrique","loc":"","date":"2026-09","stars":5,"photo":"","en":"Excellent service, a nice and clean place. I definitely recommend it.","es":"Excelente servicio, un lugar bonito y limpio. Sin duda lo recomiendo."},{"name":"Grecia","loc":"Ciudad de México","date":"2026-08","stars":5,"photo":"data:image/jpeg;base64,","en":"Excellent place, very quiet and the decor is super nice.","es":"Excelente lugar, muy tranquilo y la decoración está súper linda."},{"name":"Sergio","loc":"","date":"2026-06","stars":4,"photo":"data:image/jpeg;base64,","en":"Good place to be in Tepoztlán, without having to be in the hustle and bustle of downtown. Easily accessible by combi, in a nice area for walking, with food stalls, shops and grocery stores super close by.","es":"Buen lugar para estar en Tepoztlán sin tener que estar en el ajetreo del centro. Fácil acceso en combi, en una zona bonita para caminar, con puestos de comida, tiendas y abarrotes súper cerca."},{"name":"Ali Alexandre","loc":"Pornic, Francia","date":"2026-04","stars":5,"photo":"data:image/jpeg;base64,","en":"I had a lovely stay… I recommend this place…","es":"Pasé una estancia encantadora… Recomiendo este lugar…"},{"name":"Nephertity","loc":"Ciudad de México","date":"2025-11","stars":5,"photo":"data:image/jpeg;base64,","en":"Beautiful and excellent traveler's place, its location makes it a favorite for a comfortable and pleasant quiet stay. Great!!","es":"Un lugar hermoso y excelente para viajeros; su ubicación lo hace favorito para una estancia cómoda, agradable y tranquila. ¡¡Genial!!"},{"name":"Axell","loc":"","date":"2025-10","stars":5,"photo":"data:image/jpeg;base64,","en":"Very nice stay, quiet and comfortable :)","es":"Muy linda estancia, tranquila y cómoda :)"},{"name":"David","loc":"Toluca, México","date":"2025-09","stars":5,"photo":"data:image/jpeg;base64,","en":"Excellent service and stay. I would only recommend that they put body soap in the rooms. Everything was a 10. I would definitely come back...👌🏻!","es":"Excelente servicio y estancia. Solo recomendaría poner jabón corporal en los cuartos. Todo fue un 10. ¡Sin duda volvería...👌🏻!"},{"name":"Israel","loc":"","date":"2025-08","stars":5,"photo":"","en":"Excellent stay, very comfortable and relaxing.","es":"Excelente estancia, muy cómoda y relajante."},{"name":"André Abelardo","loc":"Puebla, México","date":"2025-08","stars":5,"photo":"data:image/jpeg;base64,","en":"A nice and quiet place to enjoy or rest in Tepoztlán.","es":"Un lugar bonito y tranquilo para disfrutar o descansar en Tepoztlán."}],"ave-suave":[{"name":"Yosset","loc":"Tuxtla Gutiérrez, México","date":"2026-01","stars":5,"photo":"data:image/jpeg;base64,","en":"Excellent place to stay, super attentive and very friendly.","es":"Excelente lugar para hospedarse, súper atentos y muy amables."},{"name":"Fer","loc":"","date":"2026-01","stars":5,"photo":"data:image/jpeg;base64,","en":"We loved it, the house is beautiful as shown in the photos and the host was very friendly and attentive. The area is quiet, although there was an event in front of the house at night, so it was a bit difficult to sleep. We arrived in about 7 minutes to the center taking the bus that passed in front of the street. It was nice to see the kittens in the garden c:","es":"Nos encantó, la casa es hermosa tal como en las fotos y el anfitrión fue muy amable y atento. La zona es tranquila, aunque hubo un evento frente a la casa en la noche y costó un poco dormir. Llegamos al centro en unos 7 minutos en el camión que pasa frente a la calle. Fue lindo ver a los gatitos en el jardín c:"},{"name":"Alitzel","loc":"Texcoco, México","date":"2025-12","stars":5,"photo":"data:image/jpeg;base64,","en":"A very comfortable place, perfect to rest from the routine. Everyone was very friendly.","es":"Un lugar muy cómodo, perfecto para descansar de la rutina. Todos fueron muy amables."},{"name":"Eman","loc":"Dammam, Arabia Saudita","date":"2025-11","stars":5,"photo":"data:image/jpeg;base64,","en":"I had the pleasure of staying at this place for 20 days. First and foremost, it's a work of art, beautifully decorated by one of the owners, who is an artist, this is evident in every detail. The location is also fantastic, it's just 2 km from the city center, providing a much quieter atmosphere while still being convenient. There’s a bus stop/cumbi less than a minute’s walk away, with service every five minutes to the center. The owners are incredible and very helpful. I also enjoyed spending time in the lovely garden, which has beautiful plants, chickens, and cats. I highly recommend this place!","es":"Tuve el gusto de quedarme aquí 20 días. Ante todo, es una obra de arte, bellamente decorada por uno de los dueños, que es artista, y se nota en cada detalle. La ubicación también es fantástica: a solo 2 km del centro, con un ambiente mucho más tranquilo pero igual de práctico. Hay una parada de camión/combi a menos de un minuto a pie, con servicio cada cinco minutos al centro. Los dueños son increíbles y muy serviciales. También disfruté mucho el jardín, con plantas hermosas, gallinas y gatos. ¡Recomiendo mucho este lugar!"},{"name":"Pedro","loc":"","date":"2025-10","stars":4,"photo":"data:image/jpeg;base64,","en":"It was a quick instance but the truth was very comfortable to come and go, everyone was very friendly and a good welcome!","es":"Fue una estancia rápida, pero la verdad muy cómodo para ir y venir, ¡todos muy amables y una buena bienvenida!"},{"name":"Abraham","loc":"Ciudad de México","date":"2025-09","stars":5,"photo":"data:image/jpeg;base64,","en":"It's a very comfortable and very cozy place.","es":"Es un lugar muy cómodo y muy acogedor."},{"name":"Joshimar","loc":"","date":"2025-08","stars":5,"photo":"","en":"A very nice place, recommended.","es":"Un lugar muy bonito, recomendado."}],"crazy-parrot":[{"name":"Daena","loc":"Calgary, Canadá","date":"2026-04","stars":5,"photo":"","en":"Really unique home and beautiful space! Hosts were very friendly and helpful. Would 100% stay here again!","es":"¡Una casa realmente única y un espacio hermoso! Los anfitriones fueron muy amables y serviciales. ¡Volvería a quedarme aquí al 100%!"},{"name":"Samanthaa","loc":"Oaxaca, México","date":"2025-10","stars":5,"photo":"data:image/jpeg;base64,","en":"A beautiful place, you feel at home, the people there are too friendly, we will definitely come back ❤️","es":"Un lugar hermoso, te sientes en casa, la gente es súper amable, sin duda volveremos ❤️"},{"name":"Jonatan","loc":"Ciudad de México","date":"2025-09","stars":5,"photo":"data:image/jpeg;base64,","en":"Very nice house, Gabriel's service was very friendly. Very good cost-value ratio.","es":"Muy bonita casa, la atención de Gabriel fue muy amable. Muy buena relación calidad-precio."},{"name":"Javiera","loc":"Cancún, México","date":"2025-08","stars":5,"photo":"data:image/jpeg;base64,","en":"Thank you very much for your kindness!","es":"¡Muchas gracias por su amabilidad!"},{"name":"Steven","loc":"","date":"2025-07","stars":5,"photo":"data:image/jpeg;base64,","en":"Beautiful home and location.","es":"Casa y ubicación hermosas."},{"name":"Magdalena","loc":"","date":"2025-05","stars":5,"photo":"data:image/jpeg;base64,","en":"Nice stay and pleasant service. They also gave us recommendations for nearby places to visit :D","es":"Linda estancia y trato agradable. También nos recomendaron lugares cercanos para visitar :D"},{"name":"Kathleen","loc":"Atlanta, EE. UU.","date":"2025-03","stars":5,"photo":"data:image/jpeg;base64,","en":"Location was a nice walk to center! The hosts were really responsive and helpful. I enjoyed my time there!","es":"¡La ubicación queda a una linda caminata del centro! Los anfitriones respondieron rápido y fueron muy serviciales. ¡Disfruté mucho mi tiempo ahí!"}]};